<?php
require_once __DIR__.'/_common.php';
$rows=sponsor_rows($conn,"SELECT p.placement_reference,p.status,p.start_date,p.end_date,p.location,p.department,pr.name programme_name,c.name cohort_name FROM placements p LEFT JOIN programmes pr ON pr.id=p.programme_id LEFT JOIN cohorts c ON c.id=p.cohort_id ORDER BY p.created_at DESC");
$all=count($rows);$completed=0;$progress=0;$pending=0;foreach($rows as $r){if($r['status']==='completed')$completed++;if(in_array($r['status'],['placed','active','placement_in_progress'],true))$progress++;if($r['status']==='pending_placement')$pending++;}
sponsor_header('Placement outcomes','Review placement lifecycle records without exposing candidate identities or internal notes.');
?>
<section class="sp-kpis"><article class="sp-kpi"><div class="sp-kpi-top"><span class="sp-kpi-label">Placement records</span><span class="sp-kpi-icon">P</span></div><strong><?= number_format($all) ?></strong><small>All statuses, including cancelled or withdrawn</small></article><article class="sp-kpi"><div class="sp-kpi-top"><span class="sp-kpi-label">Active / in progress</span><span class="sp-kpi-icon">↗</span></div><strong><?= number_format($progress) ?></strong><small>Placed, active or placement in progress</small></article><article class="sp-kpi"><div class="sp-kpi-top"><span class="sp-kpi-label">Completed</span><span class="sp-kpi-icon">✓</span></div><strong><?= number_format($completed) ?></strong><small>Marked completed in the database</small></article><article class="sp-kpi"><div class="sp-kpi-top"><span class="sp-kpi-label">Pending placement</span><span class="sp-kpi-icon">…</span></div><strong><?= number_format($pending) ?></strong><small>Awaiting placement</small></article></section>
<section class="sp-card"><div class="sp-toolbar"><input class="sp-search" type="search" placeholder="Search reference, programme, cohort, location…" data-table-search="outcomeTable" aria-label="Search outcomes"><a class="sp-btn" href="<?= sponsor_url('export.php?dataset=outcomes') ?>">↓ Export CSV</a></div><div class="sp-table-wrap"><table id="outcomeTable"><thead><tr><th>Placement reference</th><th>Programme / cohort</th><th>Status</th><th>Start date</th><th>End date</th><th>Location / department</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr data-status="<?= sponsor_e($r['status']) ?>"><td><strong><?= sponsor_e($r['placement_reference']) ?></strong></td><td><?= sponsor_e($r['programme_name'] ?: '—') ?><div class="sp-muted" style="margin-top:5px"><?= sponsor_e($r['cohort_name'] ?: '—') ?></div></td><td><span class="sp-pill <?= sponsor_e($r['status']) ?>"><?= sponsor_e(sponsor_status((string)$r['status'])) ?></span></td><td><?= sponsor_e($r['start_date']) ?></td><td><?= sponsor_e($r['end_date']) ?></td><td><?= sponsor_e($r['location'] ?: '—') ?><div class="sp-muted" style="margin-top:5px"><?= sponsor_e($r['department'] ?: '') ?></div></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="6" class="sp-empty">No placement records are available.</td></tr><?php endif; ?></tbody></table></div></section>
<div class="sp-note">This report uses placement records as stored. It excludes candidate names and internal notes. Completion is counted only where status equals <code>completed</code>; no job-retention or employment-conversion rate is inferred.</div>
<?php sponsor_footer(); ?>